(async()=>{
 const check=(name,condition,detail='')=>parent.reportTest(name,!!condition,detail);
 const tick=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 const settle=async()=>{await tick();await new Promise(resolve=>setTimeout(resolve,650));};
 const near=(a,b)=>Math.abs(a-b)<1;
 const box=id=>document.getElementById(id).getBoundingClientRect();
 const cameraSnapshot=()=>({center:map.getCenter().toArray(),zoom:map.getZoom(),point:map.project(USER_LOCATION)});
 const cameraUnchanged=before=>Math.abs(map.getZoom()-before.zoom)<1e-8&&map.getCenter().toArray().every((v,i)=>Math.abs(v-before.center[i])<1e-8)&&Math.abs(map.project(USER_LOCATION).x-before.point.x)<.01&&Math.abs(map.project(USER_LOCATION).y-before.point.y)<.01;
 try{
  await settle();
  check('147 партнёров имеют категории и описания',brands.length===147&&brands.every(b=>PARTNER_INFO[b[0]]?.length===3));
  check('2000 партнёрских точек',points.length===2000);
  const counts=new Map();for(const p of points)counts.set(p.name,(counts.get(p.name)||0)+1);
  check('У малого бизнеса 1–5 точек',PARTNERS.filter(p=>p.service==='Self Service').every(p=>counts.get(p.name)>=1&&counts.get(p.name)<=5));
  check('У крупных партнёров больше пяти точек',PARTNERS.filter(p=>p.service==='Full Service').every(p=>counts.get(p.name)>5));
  check('У всех точек уникальны адреса и здания',new Set(points.map(p=>p.address)).size===2000&&new Set(points.map(p=>p.buildingId)).size===2000);
  check('Нет пересечений ID с товарными пинами',new Set(points.concat(goodsPoints).map(p=>p.pinId)).size===points.length+goodsPoints.length);
  check('Условия и цвета едины на партнёра',points.every(p=>['cash','maxBonuses','untilDay','condition','closingHour','color'].every(key=>p[key]===partnerByName.get(p.name)[key])));
  check('Кэшбэк 10–40%, шаг 5%',points.every(p=>p.cash>=10&&p.cash<=40&&p.cash%5===0));
  check('Кэшбэк един для всех точек партнёра',points.every(p=>p.cash===partnerCashbacks.get(p.name)));
  check('Шапка 44 px без системного статус-бара',near(document.querySelector('.screen-header').getBoundingClientRect().height,44)&&!document.querySelector('.status-bar'));
  check('Под шапкой находится полноэкранная карта',near(box('map').top,0)&&near(box('map').height,812));
  check('Градиент под Header полностью удалён',!document.querySelector('.header-gradient'));
  check('Единственный переключатель в шапке',document.querySelectorAll('.screen-header input').length===1);
  check('Активный вьюпорт включает Header',near(box('markers').top,0)&&near(box('markers').height,614));
  check('Основная шторка начинается на 614 px',near(box('offersSheet').top,614));
  check('Категории недоступны для нажатия',[...document.querySelectorAll('.category-chip')].every(el=>el.disabled));
  refreshOfferList();
  const rows=[...document.querySelectorAll('.offer-row')];
  check('Предложения отсортированы по весу',rows.length>1&&rows.every((r,i)=>!i||Number(rows[i-1].dataset.weight)>=Number(r.dataset.weight)));
  check('Список соответствует точкам активной карты',rows.map(r=>Number(r.dataset.pinId)).join()===visiblePartnerOffers().map(p=>p.pinId).join());
  const canvasOnlyPin={...points[0],name:'Under-header fixture',pinId:90001,...map.unproject([180,22])};
  const sheetOnlyPin={...points[0],name:'Under-sheet fixture',pinId:90002,...map.unproject([180,750])};
  points.push(canvasOnlyPin,sheetOnlyPin);
  check('Пин под Header учитывается, пин под шторкой исключён',visiblePartnerOffers().some(p=>p.pinId===90001)&&!visiblePartnerOffers().some(p=>p.pinId===90002));
  points.splice(-2);
  const attribution=document.querySelector('.maplibregl-ctrl-attrib');
  check('Атрибуция закрыта шторкой',attribution&&attribution.getBoundingClientRect().top>=box('offersSheet').top);
  check('Прокрутка списка заблокирована до раскрытия',getComputedStyle(sheetElements.offersScroll).overflowY==='hidden');
  const controlsTop=document.querySelector('.zoom').getBoundingClientRect().top;
  const controlsCamera=cameraSnapshot();
  document.getElementById('zin').click();await new Promise(resolve=>setTimeout(resolve,500));
  check('Кнопка приближения увеличивает зум',map.getZoom()>controlsCamera.zoom+.9);
  document.getElementById('zout').click();await new Promise(resolve=>setTimeout(resolve,500));
  check('Кнопка отдаления возвращает зум',Math.abs(map.getZoom()-controlsCamera.zoom)<.01);
  map.panBy([80,30],{duration:0});document.getElementById('locate').click();await new Promise(resolve=>setTimeout(resolve,650));
  check('Кнопка геолокации возвращает к исходной точке',map.getCenter().toArray().every((v,i)=>Math.abs(v-USER_LOCATION[i])<1e-6));
  render();refreshOfferList();
  const clusterBeforeClick=document.querySelector('.cluster'),zoomBeforeCluster=map.getZoom();
  clusterBeforeClick.click();await new Promise(resolve=>setTimeout(resolve,650));
  check('Клик по старому кластеру раскрывает его приближением',map.getZoom()>zoomBeforeCluster+.9);
  map.jumpTo({center:controlsCamera.center,zoom:controlsCamera.zoom});render();refreshOfferList();
  const tileZoom=getQuadkeyZoom(map.getZoom()),grouped=getTileClusters(points,tileZoom);
  const visibleKeys=new Set(getVisibleTiles(tileZoom).map(t=>t.key));
  const expectedItems=points.filter(p=>{const tile=lngLatToTile(p.lng,p.lat,tileZoom);return visibleKeys.has(tileToQuadkey(tile.x,tile.y,tileZoom));}).length;
  check('Старая кластеризация учитывает полные тайлы как в v63',grouped.singles.length+grouped.clusters.reduce((sum,g)=>sum+g.count,0)===expectedItems);
  const cluster=document.querySelector('.cluster');
  check('В старой логике есть тайловые кластеры',!!cluster);
  const idlePosition=cluster?.style.cssText;
  await new Promise(resolve=>setTimeout(resolve,800));
  check('На неподвижной карте кластеры не дрожат',cluster?.isConnected&&cluster.style.cssText===idlePosition);
  for(let i=0;i<60;i++)map.fire('move');
  check('Кадры движения не пересоздают старые кластеры',cluster?.isConnected);
  map.panBy([30,10],{duration:300});await new Promise(resolve=>setTimeout(resolve,120));
  check('При панорамировании сохраняются DOM-узлы кластеров',cluster?.isConnected);
  await new Promise(resolve=>setTimeout(resolve,350));render();refreshOfferList();
  const savedCount=document.querySelectorAll('.offer-row').length;
  const beforeSheet=cameraSnapshot();
  let cameraEvents=0;const onSheetCamera=()=>cameraEvents++;map.on('move',onSheetCamera);
  toggleSheet('list');await settle();
  check('Первое раскрытие списка останавливается на высоте карточки',near(box('offersSheet').top,272)&&sheetState.listIntermediate&&!sheetState.listExpanded);
  check('Промежуточное положение не разрешает прокрутку',getComputedStyle(sheetElements.offersScroll).overflowY==='hidden');
  toggleSheet('list');await settle();
  check('Открытие списка сохраняет экранное положение карты',cameraUnchanged(beforeSheet)&&cameraEvents===0);
  check('Список поднимается к Header',near(box('offersSheet').top,44));
  check('Полностью раскрытая шторка разрешает прокрутку',getComputedStyle(sheetElements.offersScroll).overflowY==='auto');
  check('Шторка у Header убирает скругления',sheetElements.offers.classList.contains('docked')&&getComputedStyle(sheetElements.offers).borderTopLeftRadius==='0px');
  check('Header окрашен в фон шторки',sheetElements.wrap.classList.contains('sheet-docked'));
  check('Ручка растворяется и категории прилегают к Header',sheetElements.offers.querySelector('.sheet-grip').getBoundingClientRect().height<1&&near(sheetElements.categories.getBoundingClientRect().top,44));
  check('Анимации растворения для Header, ручки и кнопок имеют длительность 300 ms',getComputedStyle(document.querySelector('.zoom')).transitionDuration==='0.3s'&&getComputedStyle(document.querySelector('.screen-header'),'::before').transitionDuration==='0.3s'&&getComputedStyle(sheetElements.offers.querySelector('.sheet-grip')).transitionDuration.split(',').every(v=>v.trim()==='0.3s'));
  check('Кнопки карты скрыты без смещения',getComputedStyle(document.querySelector('.zoom')).opacity==='0'&&near(document.querySelector('.zoom').getBoundingClientRect().top,controlsTop));
  sheetElements.offersScroll.scrollTop=300;await tick();
  check('Категории остаются у Header при прокрутке',near(sheetElements.categories.getBoundingClientRect().top,44)&&sheetElements.offersScroll.scrollTop>0);
  sheetElements.offersScroll.scrollTop=0;
  check('Развёрнутый список сохраняет предложения',document.querySelectorAll('.offer-row').length===savedCount&&sheetElements.empty.hidden);
  toggleSheet('list');await settle();
  check('Список сворачивается в активное состояние',near(box('offersSheet').top,614)&&near(box('markers').height,614));
  check('Сворачивание списка не двигает камеру',cameraUnchanged(beforeSheet)&&cameraEvents===0);map.off('move',onSheetCamera);
  check('После сворачивания прокрутка снова заблокирована',getComputedStyle(sheetElements.offersScroll).overflowY==='hidden');
  check('Кнопки возвращаются на прежнее место',getComputedStyle(document.querySelector('.zoom')).opacity==='1'&&near(document.querySelector('.zoom').getBoundingClientRect().top,controlsTop));
  const dragList=(dy)=>{
   const target=sheetElements.offers.querySelector('.sheet-grip');
   target.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:98,button:0,clientX:180,clientY:300}));
   const capture=sheetElements.offers.setPointerCapture;sheetElements.offers.setPointerCapture=()=>{};
   window.dispatchEvent(new PointerEvent('pointermove',{pointerId:98,clientX:180,clientY:300+dy}));
   window.dispatchEvent(new PointerEvent('pointerup',{pointerId:98,clientX:180,clientY:300+dy}));
   sheetElements.offers.setPointerCapture=capture;
  };
  dragList(-500);await settle();
  check('Быстрый жест не пропускает промежуточное положение',near(box('offersSheet').top,272)&&listStage()===1);
  dragList(-260);await settle();
  check('Второй жест раскрывает список полностью',near(box('offersSheet').top,44)&&listStage()===2);
  dragList(250);await settle();
  check('Жест вниз из полного положения возвращает промежуточное',near(box('offersSheet').top,272)&&listStage()===1);
  dragList(350);await settle();
  check('Следующий жест вниз возвращает исходное положение',near(box('offersSheet').top,614)&&listStage()===0);
  const wheel=new WheelEvent('wheel',{deltaY:100,bubbles:true,cancelable:true});sheetElements.offersScroll.dispatchEvent(wheel);
  check('Колесо сначала раскрывает шторку, не прокручивая список',wheel.defaultPrevented&&sheetState.listIntermediate&&sheetElements.offersScroll.scrollTop===0);
  await settle();setListStage(0);await settle();
  const chosen=visiblePartnerOffers()[0];const cashBefore=chosen.cash;
  const beforeSelection=cameraSnapshot();
  selectPoint(chosen);
  check('Карточка пина начинает появление ниже экрана',box('detailSheet').top>=811);
  check('Основная шторка получает положение под экраном',parseFloat(sheetElements.offers.style.top)>812);
  await settle();
  check('Открывается шторка выбранного пина',!sheetElements.detail.hidden&&document.getElementById('detailName').textContent===chosen.name);
  check('Активная область выбранного пина 272 px с Header',near(box('markers').top,0)&&near(box('markers').height,272)&&near(box('detailSheet').top,272));
  check('Карточка пина блокирует прокрутку до раскрытия',getComputedStyle(sheetElements.detailScroll).overflowY==='hidden');
  check('Карточка скрывает кнопки карты без перемещения',getComputedStyle(document.querySelector('.zoom')).opacity==='0'&&near(document.querySelector('.zoom').getBoundingClientRect().top,controlsTop));
  check('Основная шторка ушла под экран и не перехватывает ввод',box('offersSheet').top>=812&&sheetElements.offers.inert);
  check('Карточка расположена поверх основной шторки',Number(getComputedStyle(sheetElements.detail).zIndex)>Number(getComputedStyle(sheetElements.offers).zIndex));
  check('Скругления карточки пина 20 px',getComputedStyle(sheetElements.detail).borderTopLeftRadius==='20px'&&getComputedStyle(sheetElements.detail).borderTopRightRadius==='20px');
  check('Партнёрский кэшбэк в карточке',document.getElementById('detailCash').textContent==='Кэшбэк '+cashBefore+'%');
  check('Категория и описание выбранного партнёра',document.getElementById('detailCategory').textContent===PARTNER_INFO[chosen.name][0]&&document.getElementById('detailAbout').textContent===PARTNER_INFO[chosen.name][1]);
  check('В карточке адрес выбранного здания',document.getElementById('detailAddress').textContent===chosen.address);
  check('В карточке максимум бонусов партнёра',document.getElementById('detailLimit').textContent===`Максимум — ${chosen.maxBonuses} бонусов`);
  check('В карточке условие и ноябрьская дата',document.getElementById('detailTerms').textContent===`${chosen.condition} до ${chosen.untilDay} ноября`);
  check('В карточке время работы партнёра',document.getElementById('detailHours').textContent===`Ежедневно 08:00 – ${String(chosen.closingHour).padStart(2,'0')}:00`);
  check('Логотип выбранного партнёра',document.getElementById('detailLogo').getAttribute('src')===chosen.logo);
  check('Выбранный пин единственный',document.querySelectorAll('.marker.selected').length===1);
  const toggle=document.getElementById('newLogicToggle');toggle.checked=true;toggle.onchange();await settle();
  check('Переключение логики сохраняет выбранное предложение',sheetState.selected===chosen&&!sheetElements.detail.hidden&&near(box('markers').height,272));
  toggle.checked=false;toggle.onchange();await settle();
  check('Выбранный пин центрирован между Header и карточкой',near(map.project([chosen.lng,chosen.lat]).x,187.5)&&near(map.project([chosen.lng,chosen.lat]).y,158));
  check('При выборе зум повышен минимум до 15',Math.abs(map.getZoom()-Math.max(SELECTED_PIN_MIN_MAP_ZOOM,beforeSelection.zoom))<1e-8);
  const afterSelection=cameraSnapshot();
  toggleSheet('detail');await settle();
  check('Подъём карточки ограничен высотой содержимого',near(box('detailSheet').top,expandedSheetTop('detail'))&&box('detailSheet').top>=44);
  check('Раскрытие карточки не меняет положение карты',cameraUnchanged(afterSelection));
  check('Карточка разрешает прокрутку только при максимальном раскрытии',getComputedStyle(sheetElements.detailScroll).overflowY==='auto');
  // A gesture begun with a scroll offset stays a scroll until pointerup.
  const dragDetail=(dy)=>{
   const target=sheetElements.detailScroll;
   target.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:99,button:0,clientX:180,clientY:200}));
   // Synthetic pointers cannot take native capture; test the same handler with capture stubbed.
   const capture=sheetElements.detail.setPointerCapture;
   sheetElements.detail.setPointerCapture=()=>{};
   window.dispatchEvent(new PointerEvent('pointermove',{bubbles:true,pointerId:99,clientX:180,clientY:200+dy}));
   window.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:99,clientX:180,clientY:200+dy}));
   sheetElements.detail.setPointerCapture=capture;
  };
  const scrollFixture=document.createElement('div');scrollFixture.style.minHeight='400px';
  sheetElements.detail.querySelector('.detail-content').append(scrollFixture);layoutSheets();await settle();
  sheetElements.detailScroll.scrollTop=80;await tick();
  dragDetail(40);
  check('Жест вниз прокручивает содержимое обратно',sheetElements.detailScroll.scrollTop===40&&sheetState.selected===chosen&&sheetState.detailExpanded);
  dragDetail(120);
  check('Достижение верха не закрывает шторку в том же жесте',sheetElements.detailScroll.scrollTop===0&&sheetState.selected===chosen&&sheetState.detailExpanded);
  stopScrollMotion(sheetElements.detailScroll);
  sheetElements.detailScroll.scrollTop=0;
  releaseScroll(sheetElements.detailScroll,1);
  await new Promise(resolve=>setTimeout(resolve,120));
  check('После отпускания прокрутка продолжается по инерции',sheetElements.detailScroll.scrollTop>30);
  stopScrollMotion(sheetElements.detailScroll);
  const maxScroll=sheetElements.detailScroll.scrollHeight-sheetElements.detailScroll.clientHeight;
  paintScroll(sheetElements.detailScroll,maxScroll+80);
  check('За границей скролла действует упругое сопротивление',Math.abs(new DOMMatrix(getComputedStyle(scrollContent(sheetElements.detailScroll)).transform).m42)>0&&Math.abs(new DOMMatrix(getComputedStyle(scrollContent(sheetElements.detailScroll)).transform).m42)<80);
  releaseScroll(sheetElements.detailScroll,0,maxScroll+80);
  await new Promise(resolve=>setTimeout(resolve,1000));
  check('Bounce возвращает содержимое к границе',!scrollMotions.has(sheetElements.detailScroll)&&scrollContent(sheetElements.detailScroll).style.transform==='');
  scrollFixture.remove();
  check('Фокус не рисует рамку',getComputedStyle(document.getElementById('closeDetail')).outlineStyle==='none');
  check('Текст и изображения не выделяются',getComputedStyle(document.getElementById('detailName')).userSelect==='none'&&getComputedStyle(document.getElementById('detailLogo')).webkitUserDrag==='none');
  map.zoomTo(map.getZoom()+1,{duration:0});await tick();const beforeClose=cameraSnapshot();
  document.getElementById('closeDetail').click();
  check('Закрытие карточки анимировано вниз',!sheetElements.detail.hidden&&parseFloat(sheetElements.detail.style.top)>812);
  await settle();
  check('Закрытие сохраняет текущий зум и центр карты',cameraUnchanged(beforeClose));
  check('Общая шторка возвращается на место',near(box('offersSheet').top,614));
  check('Закрытие карточки восстанавливает карту',sheetElements.detail.hidden&&!sheetElements.offers.inert&&near(box('markers').height,614));
  const oldCamera={center:map.getCenter().toArray(),zoom:map.getZoom()};
  map.jumpTo({center:[0,0],zoom:16});render();await tick();refreshOfferList();
  check('Пустая область показывает zero state',!sheetElements.empty.hidden&&sheetElements.list.hidden&&document.querySelectorAll('.offer-row').length===0);
  setSheetExpanded('list',true);await settle();
  check('Короткая пустая шторка поднимается только на высоту контента',box('offersSheet').top>44&&near(box('offersSheet').top,expandedSheetTop('list')));
  setListStage(0);map.jumpTo(oldCamera);render();await settle();
  document.getElementById('newLogicToggle').checked=true;fitInitialNewLogicArea();render();await settle();refreshOfferList();
  const newRows=[...document.querySelectorAll('.offer-row')];
  check('Сортировка сохранена в новой логике',newRows.length>1&&newRows.every((r,i)=>!i||Number(newRows[i-1].dataset.weight)>=Number(r.dataset.weight)));
  const highZoomPin=visiblePartnerOffers()[0];
  map.jumpTo({zoom:16.25});
  selectPoint(highZoomPin);await settle();
  check('Выбор пина сохраняет зум выше 15',near(map.getZoom(),16.25));
  check('Новая логика открывает один выбранный пин',!sheetElements.detail.hidden&&document.querySelectorAll('.marker.selected').length===1&&near(box('markers').height,272),JSON.stringify({count:document.querySelectorAll('.marker.selected').length,height:box('markers').height,top:box('detailSheet').top}));
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await settle();
  check('Escape закрывает выбранное предложение',sheetElements.detail.hidden);
  const currentCash=new Map(points.map(p=>[p.name,p.cash]));
  map.zoomTo(map.getZoom()+1,{duration:0});render();await tick();
  check('Проценты сохраняются при перемещении, масштабировании и выборе',points.every(p=>currentCash.get(p.name)===p.cash));
  const images=[...document.querySelectorAll('img[src^="assets/"]')];
  await Promise.all(images.map(img=>img.decode().catch(()=>{})));
  check('Все статические изображения загружены',images.every(img=>img.complete&&img.naturalWidth>0));
  check('Нет горизонтального переполнения',document.documentElement.scrollWidth===375);
  await runNewPinTests(check,settle);
  parent.reportTest('Проверки завершены',true);
 }catch(error){parent.reportTest('Исключение в тестах',false,error.stack);}
})();
